    # Try to infer simple goal: stay or move toward some heuristic
    # Use only observation.get as required, and constrain moves to [-1,0,1]

    # Default move
    dx = 0
    dy = 0

    # Try to detect goals in common fields without assuming structure
    # Prefer moving toward "food" or "resource" if present
    target_x = observation.get("target_x")
    target_y = observation.get("target_y")
    if target_x is None or target_y is None:
        # Try more generic fields
        goal = observation.get("goal")
        if isinstance(goal, dict):
            target_x = goal.get("x")
            target_y = goal.get("y")
        if target_x is None or target_y is None:
            # Try best-effort: if there is a "player" with position, move toward center
            you = observation.get("you") or observation.get("player") or observation.get("self")
            if isinstance(you, dict):
                cx = you.get("x")
                cy = you.get("y")
                if cx is not None and cy is not None:
                    # Move toward own position? No. Instead, try center heuristic if center known
                    grid_center_x = observation.get("grid_center_x")
                    grid_center_y = observation.get("grid_center_y")
                    if grid_center_x is not None and grid_center_y is not None:
                        target_x, target_y = grid_center_x, grid_center_y

    # If we have a target, move one step toward it (clamped to -1..1)
    if target_x is not None and target_y is not None:
        # Current position
        x = observation.get("x")
        y = observation.get("y")
        if x is not None and y is not None:
            if target_x > x:
                dx = 1
            elif target_x < x:
                dx = -1
            else:
                dx = 0

            if target_y > y:
                dy = 1
            elif target_y < y:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # Fallback: try to move away from nearest known threat if present
    threat_x = observation.get("threat_x")
    threat_y = observation.get("threat_y")
    if threat_x is not None and threat_y is not None:
        x = observation.get("x")
        y = observation.get("y")
        if x is not None and y is not None:
            if threat_x > x:
                dx = -1
            elif threat_x < x:
                dx = 1
            else:
                dx = 0

            if threat_y > y:
                dy = -1
            elif threat_y < y:
                dy = 1
            else:
                dy = 0
            return [dx, dy]

    # Last resort: stay in place
    return [0, 0]

